/**
 * The long tail of screens (docs/stanley-answers-plan.md, Phase 5): one line per thing a guest might ask for that has a screen of its own. Each line is a topic, the nouns that point to it (one concept, `n.<id>`), a few
 * plain questions that must reach it (the corpus), and the screens to offer. The builders in `lexicon.ts`, `topics.ts`, `destinations.ts` and `corpus/topics.ts` turn a line into all four, so a screen is added in one place.
 * A pill is the screen's own title; the words for the topic are `name`. A phrase is several words on purpose: a long tail topic must never be fired by one common word.
 *  - `dests`: `name=SCREENID`, the first is offered first.
 *  - `high`: a risk topic, shown only as the official screens, with no claim from the engine.
 */
export interface ScreenSpec { id: string; name: string; words: string; say: string; dests: string; high?: boolean }

const S = (id: string, name: string, words: string, say: string, dests: string, high = false): ScreenSpec => ({ id, name, words, say, dests, high })

